ALTER TABLE opportunities ADD last_contact_at DATETIME NULL, ADD closed_at DATETIME NULL, ADD reopened_at DATETIME NULL, ADD INDEX idx_commercial_stage(broker_id,stage,updated_at);
CREATE TABLE properties (id CHAR(32) PRIMARY KEY,reference_code VARCHAR(60) NOT NULL UNIQUE,title VARCHAR(180) NOT NULL,property_type VARCHAR(100) NOT NULL,address VARCHAR(255) NULL,region VARCHAR(150) NULL,purpose ENUM('purchase','rental','both') NOT NULL,price DECIMAL(13,2) NOT NULL,status ENUM('available','reserved','sold','rented','inactive') NOT NULL DEFAULT 'available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CHECK(price>0));
CREATE TABLE opportunity_properties (opportunity_id CHAR(32) NOT NULL,property_id CHAR(32) NOT NULL,presented_by CHAR(32) NOT NULL,notes TEXT NULL,presented_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(opportunity_id,property_id),FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE,FOREIGN KEY(property_id) REFERENCES properties(id),FOREIGN KEY(presented_by) REFERENCES users(id));
CREATE TABLE visits (id CHAR(32) PRIMARY KEY,opportunity_id CHAR(32) NOT NULL,property_id CHAR(32) NOT NULL,broker_id CHAR(32) NOT NULL,scheduled_at DATETIME NOT NULL,location VARCHAR(255) NOT NULL,notes TEXT NULL,status ENUM('scheduled','completed','cancelled','no_show') NOT NULL DEFAULT 'scheduled',cancellation_reason VARCHAR(255) NULL,result TEXT NULL,feedback TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE,FOREIGN KEY(property_id) REFERENCES properties(id),FOREIGN KEY(broker_id) REFERENCES users(id),INDEX(broker_id,scheduled_at,status));
CREATE TABLE proposals (id CHAR(32) PRIMARY KEY,opportunity_id CHAR(32) NOT NULL,property_id CHAR(32) NOT NULL,created_by CHAR(32) NOT NULL,proposal_type ENUM('purchase','rental') NOT NULL,amount DECIMAL(13,2) NOT NULL,commercial_terms TEXT NULL,proposal_date DATE NOT NULL,valid_until DATE NULL,status ENUM('draft','sent','under_review','accepted','rejected','cancelled') NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE,FOREIGN KEY(property_id) REFERENCES properties(id),FOREIGN KEY(created_by) REFERENCES users(id),CHECK(amount>0),INDEX(opportunity_id,status));
CREATE TABLE proposal_events (id CHAR(32) PRIMARY KEY,proposal_id CHAR(32) NOT NULL,user_id CHAR(32) NOT NULL,event_type VARCHAR(50) NOT NULL,previous_data JSON NULL,new_data JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(proposal_id) REFERENCES proposals(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE negotiations (id CHAR(32) PRIMARY KEY,opportunity_id CHAR(32) NOT NULL,proposal_id CHAR(32) NULL,user_id CHAR(32) NOT NULL,amount DECIMAL(13,2) NULL,notes TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE,FOREIGN KEY(proposal_id) REFERENCES proposals(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE closings (id CHAR(32) PRIMARY KEY,opportunity_id CHAR(32) NOT NULL UNIQUE,property_id CHAR(32) NULL,responsible_id CHAR(32) NOT NULL,outcome ENUM('won','lost') NOT NULL,business_type ENUM('purchase','rental') NULL,final_amount DECIMAL(13,2) NULL,closing_date DATE NOT NULL,loss_reason VARCHAR(255) NULL,notes TEXT NULL,contract_reference VARCHAR(100) NULL,contract_status ENUM('not_started','draft','signed','cancelled') NULL,contract_file_path VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id),FOREIGN KEY(property_id) REFERENCES properties(id),FOREIGN KEY(responsible_id) REFERENCES users(id),CHECK(final_amount IS NULL OR final_amount>0));
